files.values.py:
"""Values that flow through an algorithm: tokens, pairs, distributions."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Generic, TypeVar

K = TypeVar("K")
V = TypeVar("V")
T = TypeVar("T")

# A position ID is an int; the alias documents intent in signatures.
Position = int


class Token(str):
    """A prompt token: a string (without surrounding spaces) that also knows
    its index in the prompt."""

    index: int
    raw: str

    def __new__(cls, text: str, index: int) -> "Token":
        obj = super().__new__(cls, str(text).strip())
        obj.index = index
        obj.raw = str(text)
        return obj

    def __reduce__(self):
        return (Token, (self.raw, self.index))

    # Values are immutable, so copies of a trace can share them. Without this,
    # deepcopy rebuilds every token through __reduce__ on each intervention.
    def __copy__(self) -> "Token":
        return self

    def __deepcopy__(self, memo: dict) -> "Token":
        return self


@dataclass(frozen=True)
class Pair(Generic[K, V]):
    """A key : value pair. Keys and values can themselves be pairs."""

    key: K
    value: V

    def __str__(self) -> str:
        def side(x: Any) -> str:
            return f"({show(x)})" if isinstance(x, Pair) else show(x)

        return f"{side(self.key)}:{side(self.value)}"

    def __copy__(self) -> "Pair[K, V]":
        return self

    def __deepcopy__(self, memo: dict) -> "Pair[K, V]":
        return self


@dataclass(frozen=True)
class Distribution:
    """A distribution over labels; visualizations show its top label."""

    items: tuple[tuple[str, float], ...]

    def top(self) -> tuple[str, float]:
        best = self.items[0]
        for item in self.items[1:]:
            if item[1] > best[1]:
                best = item
        return best

    def label(self) -> str:
        """The top label, or tied top labels joined with " / "."""
        best = self.top()[1]
        return " / ".join(label for label, p in self.items if best - p < 0.01)

    def __str__(self) -> str:
        return self.label()

    def __copy__(self) -> "Distribution":
        return self

    def __deepcopy__(self, memo: dict) -> "Distribution":
        return self


def key_of(value: Any) -> tuple | None:
    """Identity used for "did this value change" checks."""
    if value is None:
        return None
    if isinstance(value, str):
        return ("s", value.strip())
    if isinstance(value, Pair):
        return ("pair", key_of(value.key), key_of(value.value))
    if isinstance(value, Distribution):
        return ("d", tuple((label, round(p * 100)) for label, p in value.items))
    if isinstance(value, bool):
        return ("b", value)
    if isinstance(value, (int, float)):
        return ("n", value)
    return ("o", repr(value))


def show(value: Any) -> str:
    """How a value is displayed in a grid cell."""
    if value is None:
        return "∅"
    if isinstance(value, Distribution):
        return value.label()
    return str(value)

files.vartypes.py:
"""Variable types: string, int, position ID, and key : value pairs.

Types are JSON-shaped dicts, shared with workbench's TypeScript engine:

    {"kind": "string"} | {"kind": "int"} | {"kind": "position"}
    | {"kind": "pair", "key": <type>, "value": <type>}

Primitive signatures also use patterns: {"kind": "var", "name": "K"} for a
type variable and {"kind": "list", "of": <pattern>} for a list argument.
"""

from __future__ import annotations

from typing import Any

STRING = {"kind": "string"}
INT = {"kind": "int"}
POSITION = {"kind": "position"}
BASIC = ("string", "int", "position")

Type = dict[str, Any]


def pair(key: Type, value: Type) -> Type:
    return {"kind": "pair", "key": key, "value": value}


def list_of(of: Type) -> Type:
    return {"kind": "list", "of": of}


def var(name: str) -> Type:
    return {"kind": "var", "name": name}


def is_type(t: Any) -> bool:
    """Whether `t` is a concrete variable type (no patterns)."""
    if not isinstance(t, dict):
        return False
    if t.get("kind") in BASIC:
        return True
    return t.get("kind") == "pair" and is_type(t.get("key")) and is_type(t.get("value"))


def describe(t: Type | None, subst: dict[str, Type] | None = None) -> str:
    """Readable name: "position", "list of string", "position : string"."""
    if t is None:
        return "unknown"
    kind = t["kind"]
    if kind == "var":
        bound = (subst or {}).get(t["name"])
        return describe(bound) if bound else f"any type ({t['name']})"
    if kind == "list":
        return f"list of {describe(t['of'], subst)}"
    if kind == "pair":

        def side(x: Type) -> str:
            s = describe(x, subst)
            return f"({s})" if x.get("kind") == "pair" else s

        return f"{side(t['key'])} : {side(t['value'])}"
    return kind


def unify(pattern: Type, t: Type, subst: dict[str, Type]) -> bool:
    """Match a concrete type against a pattern, binding type variables."""
    kind = pattern["kind"]
    if kind == "var":
        bound = subst.get(pattern["name"])
        if bound is None:
            subst[pattern["name"]] = t
            return True
        return bound == t
    if kind == "pair":
        return t.get("kind") == "pair" and unify(pattern["key"], t["key"], subst) and unify(pattern["value"], t["value"], subst)
    return t.get("kind") == kind


def substitute(pattern: Type, subst: dict[str, Type]) -> Type | None:
    """The concrete type a pattern stands for, or None if a variable is unbound."""
    kind = pattern["kind"]
    if kind == "var":
        return subst.get(pattern["name"])
    if kind == "pair":
        k = substitute(pattern["key"], subst)
        v = substitute(pattern["value"], subst)
        return pair(k, v) if k is not None and v is not None else None
    if kind == "list":
        of = substitute(pattern["of"], subst)
        return list_of(of) if of is not None else None
    return dict(pattern)

files.primitives.py:
"""Built-in functions a variable can use, with typed, named arguments.

The editor shows each function's source exactly as written here, and turning a
primitive into a custom Python function starts from this source, so keep each
one short and readable. Code generation calls them with keyword arguments named
after their slots. They must stay pure: no I/O, randomness or global state.

The TypeScript engine in workbench (src/lib/algorithmHypothesis) implements the
same functions and stores these sources; the golden tests keep them in sync.
"""

from __future__ import annotations

import inspect
from dataclasses import dataclass, field
from typing import Any, Callable

from algorithm_hypothesis import vartypes as vt
from algorithm_hypothesis.values import Distribution, K, Pair, Position, T, Token, V, show

# ----------------------------------------------------------------- functions


def position_id(token: str, specials: list[str]) -> Pair[Position, str]:
    """The token's position ID, stored as position ID : token. Each distinct
    special token (such as a name) gets the next ID in order of first
    appearance, so a name mentioned again gets its first mention's ID.
    `specials` are the special tokens up to this one; a possessive ('s) is
    ignored when comparing them."""

    def name(t):
        return str(t).strip().split("'")[0]

    ids = {}
    for t in specials:
        if t is not None:
            ids.setdefault(name(t), len(ids) + 1)
    if token is None or name(token) not in ids:
        return None
    return Pair(ids[name(token)], token)


def copy(x: T) -> T:
    """The value, unchanged, in another cell. Copying a token carries the
    token itself."""
    return x


def pair(key: K, value: V) -> Pair[K, V]:
    """Bind a key to a value."""
    return Pair(key, value)


def retrieve(key: K, pairs: list[Pair[K, V]], *, match: str = "key") -> V | None:
    """The value of the first pair whose key equals `key`, the way attention
    matches a query against keys and reads the matching value. With
    match="value", the first value equal to `key`: dereferencing a pointer,
    which finds nothing if that value isn't in context."""
    for p in pairs:
        if key is None or not isinstance(p, Pair):
            continue
        if (p.key if match == "key" else p.value) == key:
            return p.value
    return None


def index(i: Position, values: list[V]) -> V | None:
    """The i-th value, counting from 1."""
    if isinstance(i, int) and 1 <= i <= len(values):
        return values[i - 1]
    return None


def key_of(pair: Pair[K, V]) -> K | None:
    """The key of a key : value pair, such as the position ID of 4:Tim."""
    return pair.key if isinstance(pair, Pair) else None


def value_of(pair: Pair[K, V]) -> V | None:
    """The value of a key : value pair, such as the token of 4:Tim."""
    return pair.value if isinstance(pair, Pair) else None


def mixture(answers: list[V], *, weights: str = "") -> Distribution:
    """A linear combination of the answers, such as one per mechanism: each
    answer gets its weight, and the weights of equal answers add up.
    `weights` lists one weight per answer, separated by commas; a missing
    weight is 1. The result is normalized to sum to 1."""
    w = [float(x) for x in weights.split(",") if x.strip()]
    w = (w + [1.0] * len(answers))[: len(answers)]
    total = sum(w) or 1.0
    p: dict[str, float] = {}
    for answer, weight in zip(answers, w):
        p[show(answer)] = p.get(show(answer), 0.0) + weight / total
    return Distribution(tuple(p.items()))


def constant(*, value: str = "", type: str = "string") -> str | int | None:
    """A fixed value."""
    if value == "":
        return None
    return value if type == "string" else int(value)


# ------------------------------------------------- helpers for generated code


def as_token(text, index):
    """Wrap a token's text, as carried through the residual stream, with its index."""
    return None if text is None else Token(text, index)


def render(tok):
    """raw_input for generated models: the prompt's tokens, space-separated."""
    return " ".join(str(t).strip() for t in tok)


def display(value):
    """raw_output for generated models: the output as shown in the grid."""
    return show(value)


# ------------------------------------------------------------------ registry


@dataclass(frozen=True)
class Slot:
    name: str
    type: dict  # a pattern; {"kind": "list", ...} means the slot takes a list

    @property
    def many(self) -> bool:
        return self.type["kind"] == "list"


@dataclass(frozen=True)
class Option:
    name: str
    default: Any
    choices: tuple | None = None


@dataclass(frozen=True)
class Primitive:
    name: str
    label: str
    slots: tuple[Slot, ...]
    returns: dict | None  # None: set by the "type" option (constant)
    options: tuple[Option, ...] = field(default_factory=tuple)
    fn: Callable[..., Any] | None = None
    # Slots and return type under other option values, if they differ.
    retype: Callable[[dict], tuple[tuple[Slot, ...], dict | None] | None] | None = None

    @property
    def source(self) -> str:
        return inspect.getsource(self.fn)

    def signature(self, options: dict) -> tuple[tuple[Slot, ...], dict | None]:
        """Slots and return type for these option values."""
        alt = self.retype(options) if self.retype else None
        return alt or (self.slots, self.returns)


_K, _V, _T = vt.var("K"), vt.var("V"), vt.var("T")


def _retrieve_by_value(options: dict):
    # Matching on values: the key is compared with each pair's value.
    if options.get("match", "key") == "value":
        return (Slot("key", _V), Slot("pairs", vt.list_of(vt.pair(_K, _V)))), _V
    return None


PRIMITIVES: dict[str, Primitive] = {
    p.name: p
    for p in [
        Primitive(
            "position_id",
            "Position ID",
            (Slot("token", vt.STRING), Slot("specials", vt.list_of(vt.STRING))),
            vt.pair(vt.POSITION, vt.STRING),
            (),
            position_id,
        ),
        Primitive("copy", "Copy", (Slot("x", _T),), _T, (), copy),
        Primitive("pair", "Pair", (Slot("key", _K), Slot("value", _V)), vt.pair(_K, _V), (), pair),
        Primitive(
            "retrieve",
            "Retrieve",
            (Slot("key", _K), Slot("pairs", vt.list_of(vt.pair(_K, _V)))),
            _V,
            (Option("match", "key", ("key", "value")),),
            retrieve,
            _retrieve_by_value,
        ),
        Primitive("index", "Index", (Slot("i", vt.POSITION), Slot("values", vt.list_of(_V))), _V, (), index),
        Primitive("key_of", "KeyOf", (Slot("pair", vt.pair(_K, _V)),), _K, (), key_of),
        Primitive("value_of", "ValueOf", (Slot("pair", vt.pair(_K, _V)),), _V, (), value_of),
        Primitive("mixture", "Mixture", (Slot("answers", vt.list_of(_V)),), vt.STRING, (Option("weights", ""),), mixture),
        Primitive(
            "constant",
            "Constant",
            (),
            None,
            (Option("value", ""), Option("type", "string", ("string", "int", "position"))),
            constant,
        ),
    ]
}

files.runtime.py:
"""Run custom Python functions one call at a time, without causalab.

Workbench evaluates primitives in TypeScript and sends each call of a custom
Python function to a Pyodide worker, which runs it with this module. The code
generator in compile.py strips functions the same way, so a function behaves the
same in the browser and in a compiled causalab model.

Values cross as JSON, in the shape of the TypeScript engine's values:

    null, number, boolean, string
    {"kind": "token", "text": str, "index": int}
    {"kind": "pair", "key": value, "value": value}
    {"kind": "distribution", "items": [{"label": str, "p": float}]}

The worker ships only values, vartypes, primitives and this module, so nothing
here may import causalab.
"""

from __future__ import annotations

import ast
import json
import math
import sys
import traceback
from typing import Any

from algorithm_hypothesis import primitives as _p
from algorithm_hypothesis.values import Distribution, Pair, Token, show

FILENAME = "<compute>"

# Modules the worker needs, in import order (see python_runtime_files()).
MODULES = ("values", "vartypes", "primitives", "runtime")


class FunctionError(ValueError):
    """The source doesn't define a usable compute()."""


class ReturnError(TypeError):
    """compute returned something a variable can't hold."""


# ----------------------------------------------------------- the function


def strip_function(source: str, name: str) -> tuple[ast.Module, list[str]]:
    """The module `source`, with compute() renamed `name` and its type hints
    removed, and compute's parameter names.

    Type hints document a function in the editor (``key: K``) but would need
    those generic names to evaluate. Line numbers are kept, so errors point at
    the user's own lines.
    """
    try:
        tree = ast.parse(source, filename=FILENAME)
    except SyntaxError as exc:
        raise FunctionError(f"SyntaxError: {exc.msg} (line {exc.lineno})") from exc
    fn = next((n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "compute"), None)
    if fn is None:
        raise FunctionError("The Python source must define compute(...).")
    for node in ast.walk(fn):
        if isinstance(node, ast.arg):
            node.annotation = None
    fn.returns = None
    fn.name = name
    params = [a.arg for a in fn.args.args + fn.args.kwonlyargs]
    return tree, params


def namespace(template: list[str] | tuple[str, ...]) -> dict[str, Any]:
    """What a custom function can use without importing it; the same names as
    the module compile.py generates."""
    return {
        "__name__": "algorithm_hypothesis_function",
        "math": math,
        "Distribution": Distribution,
        "Pair": Pair,
        "Token": Token,
        "show": show,
        "_p": _p,
        "TEMPLATE": tuple(template),
    }


_FUNCTIONS: dict[tuple[str, tuple[str, ...]], tuple[Any, list[str]]] = {}


def load(source: str, template: list[str] | tuple[str, ...] = ()) -> tuple[Any, list[str]]:
    """compute() from `source`, ready to call, and its parameter names."""
    key = (source, tuple(template))
    if key not in _FUNCTIONS:
        if len(_FUNCTIONS) > 256:  # every edit of a function is a new source
            _FUNCTIONS.clear()
        tree, params = strip_function(source, "compute")
        ns = namespace(template)
        exec(compile(tree, FILENAME, "exec"), ns)
        _FUNCTIONS[key] = (ns["compute"], params)
    return _FUNCTIONS[key]


# --------------------------------------------------------------- values


def from_json(v: Any) -> Any:
    if isinstance(v, list):
        return [from_json(x) for x in v]
    if isinstance(v, dict):
        kind = v.get("kind")
        if kind == "token":
            return Token(v["text"], int(v["index"]))
        if kind == "pair":
            return Pair(from_json(v.get("key")), from_json(v.get("value")))
        if kind == "distribution":
            return Distribution(tuple((str(x["label"]), float(x["p"])) for x in v["items"]))
        raise ValueError(f"Unknown value {v!r}.")
    return v


def _describe(v: Any) -> str:
    if isinstance(v, bool):
        return "a bool"
    if isinstance(v, str):
        return "a string"
    if isinstance(v, int):
        return "an int"
    if isinstance(v, Pair):
        return "a key : value pair"
    if isinstance(v, Distribution):
        return "a distribution"
    if isinstance(v, (list, tuple)):
        return "a list"
    name = type(v).__name__
    return f"an {name}" if name[:1].lower() in "aeiou" else f"a {name}"


def to_json(v: Any) -> Any:
    """A returned value as JSON; raises ReturnError for values a variable can't hold."""
    if v is None or isinstance(v, bool):
        return v
    if isinstance(v, Token):
        return {"kind": "token", "text": v.raw, "index": v.index}
    if isinstance(v, str):
        return v
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        if not math.isfinite(v):
            raise ReturnError(f"compute returned {v}, which isn't a finite number.")
        return v
    if isinstance(v, Pair):
        return {"kind": "pair", "key": to_json(v.key), "value": to_json(v.value)}
    if isinstance(v, Distribution):
        return {"kind": "distribution", "items": [{"label": label, "p": p} for label, p in v.items]}
    raise ReturnError(
        f"compute returned {_describe(v)}; a variable holds a string, an int, a position ID or a key : value pair."
    )


def type_problem(v: Any, t: dict | None) -> str | None:
    """Why `v` isn't a value of type `t`, or None. ∅ (None) fits every type."""
    if v is None or not t:
        return None
    kind = t.get("kind")
    if kind == "string":
        if isinstance(v, (str, Distribution)):
            return None
        return f"compute returned {show(v)!r} ({_describe(v)}), but this variable is a string."
    if kind in ("int", "position"):
        if isinstance(v, int) and not isinstance(v, bool):
            return None
        label = "a position ID" if kind == "position" else "an int"
        return f"compute returned {show(v)!r} ({_describe(v)}), but this variable is {label}."
    if kind == "pair":
        if not isinstance(v, Pair):
            return f"compute returned {show(v)!r} ({_describe(v)}), but this variable is a key : value pair."
        return type_problem(v.key, t.get("key")) or type_problem(v.value, t.get("value"))
    return None


# ----------------------------------------------------------------- calls


def _error_line(exc: BaseException) -> str:
    """'Name: message (line n)', with n the last line of compute that ran."""
    line = None
    for frame in traceback.extract_tb(exc.__traceback__):
        if frame.filename == FILENAME:
            line = frame.lineno
    text = f"{type(exc).__name__}: {exc}"
    return f"{text} (line {line})" if line else text


def call(source: str, args: dict[str, Any], template: list[str] | tuple[str, ...] = (), type_: dict | None = None) -> dict:
    """Run compute(**args) on JSON values. Returns {"ok": True, "value": json}
    or {"ok": False, "error": message}; never raises."""
    try:
        fn, params = load(source, template)
        kwargs = {name: from_json(v) for name, v in args.items()}
        if "template" in params and "template" not in kwargs:
            kwargs["template"] = tuple(template)
        value = fn(**kwargs)
        out = to_json(value)
        problem = type_problem(value, type_)
        if problem:
            return {"ok": False, "error": problem}
        return {"ok": True, "value": out}
    except (FunctionError, ReturnError) as exc:
        return {"ok": False, "error": str(exc)}
    except RecursionError:
        return {"ok": False, "error": "RecursionError: compute called itself too many times."}
    except Exception as exc:  # noqa: BLE001  (shown to the user in place)
        return {"ok": False, "error": _error_line(exc)}


def call_batch(requests_json: str) -> str:
    """Run several calls; the worker's entry point. Takes and returns JSON:
    [{"id", "source", "args", "template", "type"}] → [{"id", "ok", "value" | "error"}]."""
    out = []
    for req in json.loads(requests_json):
        result = call(req["source"], req.get("args") or {}, req.get("template") or (), req.get("type"))
        out.append({"id": req["id"], **result})
    return json.dumps(out, ensure_ascii=False)


def python_runtime_files() -> dict[str, str]:
    """Source of each module the worker needs, keyed by file name, with an empty
    package __init__ (the real one imports causalab)."""
    import inspect

    package = sys.modules["algorithm_hypothesis"]
    files = {"__init__.py": '"""Algorithm Hypothesis runtime for the browser (no causalab)."""\n'}
    for name in MODULES:
        module = __import__(f"{package.__name__}.{name}", fromlist=[name])
        files[f"{name}.py"] = inspect.getsource(module)
    return files
